package in.tallybridge.app;

import android.app.*;
import android.content.*;
import android.graphics.*;
import android.graphics.drawable.GradientDrawable;
import android.os.*;
import android.text.*;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.text.NumberFormat;
import java.util.*;
import java.util.concurrent.*;

/** Search customers, invoices, orders, products, LR/RR, GSTIN, mobile and amounts from one screen. */
public final class UniversalSearchActivity extends Activity {
 public static final String EXTRA_MODE="mode", MODE_CUSTOMERS="customers";
 private final ExecutorService work=Executors.newSingleThreadExecutor(); private final Handler main=new Handler(Looper.getMainLooper());
 private CryptoStore store; private BridgeApi api; private JSONArray all=new JSONArray(); private LinearLayout results; private EditText query; private ProgressBar progress;
 private boolean dark,destroyed,customersOnly; private int NAVY,TEAL,MUTED,BG,SURFACE,BORDER,TINT,INK; private String company="";
 private final NumberFormat money=NumberFormat.getCurrencyInstance(new Locale("en","IN"));
 @Override public void onCreate(Bundle b){applyTheme();super.onCreate(b);getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);money.setCurrency(Currency.getInstance("INR"));customersOnly=MODE_CUSTOMERS.equals(getIntent().getStringExtra(EXTRA_MODE));try{store=new CryptoStore(this);api=new BridgeApi(store);company=store.get("company");}catch(Exception e){finish();return;}render();load();}
 @Override protected void onDestroy(){destroyed=true;work.shutdownNow();main.removeCallbacksAndMessages(null);super.onDestroy();}
 private String appearance(){return getSharedPreferences("appearance",MODE_PRIVATE).getString("mode","System");}
 private void applyTheme(){String m=appearance();dark=m.equals("Dark")||(m.equals("System")&&(getResources().getConfiguration().uiMode&android.content.res.Configuration.UI_MODE_NIGHT_MASK)==android.content.res.Configuration.UI_MODE_NIGHT_YES);setTheme(dark?R.style.AppThemeDark:R.style.AppThemeLight);NAVY=dark?0xffe6edf3:0xff102d44;TEAL=dark?0xff7bd8bd:0xff176b5b;MUTED=dark?0xffa7b8c5:0xff596c79;BG=dark?0xff101820:0xfff5f7fa;SURFACE=dark?0xff1b2732:Color.WHITE;BORDER=dark?0xff344552:0xffe4eaef;TINT=dark?0xff203f3a:0xffe5f2ee;INK=dark?0xff102d26:Color.WHITE;}
 private int dp(float v){return Math.round(v*getResources().getDisplayMetrics().density);} private LinearLayout col(){LinearLayout x=new LinearLayout(this);x.setOrientation(LinearLayout.VERTICAL);return x;}
 private TextView txt(String s,int z,int c){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(c);v.setPadding(0,dp(3),0,dp(3));v.setLineSpacing(dp(2),1f);return v;}
 private GradientDrawable shape(int c,int r){GradientDrawable d=new GradientDrawable();d.setColor(c);d.setCornerRadius(dp(r));d.setStroke(dp(1),BORDER);return d;}
 private void render(){LinearLayout root=col();root.setBackgroundColor(BG);LinearLayout top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);top.setPadding(dp(18),dp(16),dp(18),dp(9));LinearLayout titles=col();TextView h=txt(customersOnly?"Customers":"Universal Search",25,NAVY);h.setTypeface(null,Typeface.BOLD);titles.addView(h);titles.addView(txt(customersOnly?"Find any customer and open Customer 360":"Customer • invoice • order • product • LR/RR • mobile • GSTIN",12,MUTED));top.addView(titles,new LinearLayout.LayoutParams(0,-2,1));Button back=new Button(this);back.setText("Back");back.setAllCaps(false);back.setTextColor(TEAL);back.setBackground(shape(SURFACE,12));back.setOnClickListener(v->finish());top.addView(back,new LinearLayout.LayoutParams(dp(82),dp(48)));root.addView(top);
  query=new EditText(this);query.setHint(customersOnly?"Search customer name, mobile or GSTIN":"Search anything…");query.setSingleLine(true);query.setTextSize(17);query.setTextColor(NAVY);query.setHintTextColor(MUTED);query.setPadding(dp(16),dp(13),dp(16),dp(13));query.setBackground(shape(SURFACE,14));LinearLayout.LayoutParams qp=new LinearLayout.LayoutParams(-1,-2);qp.setMargins(dp(18),dp(4),dp(18),dp(8));root.addView(query,qp);
  progress=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);progress.setIndeterminate(true);progress.setIndeterminateTintList(android.content.res.ColorStateList.valueOf(TEAL));root.addView(progress,new LinearLayout.LayoutParams(-1,dp(3)));
  ScrollView sv=new ScrollView(this);results=col();results.setPadding(dp(18),dp(4),dp(18),dp(28));sv.addView(results);root.addView(sv,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);query.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int d){}public void onTextChanged(CharSequence s,int a,int b,int c){paint();}public void afterTextChanged(Editable e){}});}
 private void load(){progress.setVisibility(View.VISIBLE);work.execute(()->{try{JSONObject x=api.get(BridgeApi.path("global-search",company));JSONArray a=x.optJSONArray("results");if(a==null)a=new JSONArray();JSONArray got=a;main.post(()->{if(destroyed)return;all=got;progress.setVisibility(View.GONE);paint();query.requestFocus();});}catch(Exception e){main.post(()->{if(destroyed)return;progress.setVisibility(View.GONE);results.removeAllViews();results.addView(txt("Search data could not be loaded.\n"+(e.getMessage()==null?"Check Windows TallyBridge connection.":e.getMessage()),15,MUTED));});}});}
 private boolean customerKind(String k){return k.equals("ledger")||k.equals("party-detail");} private boolean invoiceKind(String k){return k.equals("sales")||k.equals("purchase")||k.equals("proforma")||k.equals("invoice-detail");}
 private boolean match(JSONObject x,String q){String k=x.optString("kind");if(k.equals("followup"))return false;if(customersOnly&&!customerKind(k))return false;if(q.isEmpty())return customerKind(k)||(!customersOnly&&all.length()<=80);String hay=(x.optString("searchText")+" "+x.optString("title")+" "+x.optString("subtitle")+" "+x.optString("number")+" "+x.optString("party")+" "+x.optString("amount")).toLowerCase(Locale.ROOT);for(String token:q.split("\\s+"))if(!token.isEmpty()&&!hay.contains(token))return false;return true;}
 private String group(String k){if(customerKind(k))return "CUSTOMERS";if(invoiceKind(k))return "INVOICES & ITEMS";if(k.equals("order"))return "ORDERS";return "OTHER";}
 private void paint(){if(results==null)return;results.removeAllViews();String q=query.getText().toString().trim().toLowerCase(Locale.ROOT);LinkedHashMap<String,List<JSONObject>> groups=new LinkedHashMap<>();for(String g:new String[]{"CUSTOMERS","INVOICES & ITEMS","ORDERS","OTHER"})groups.put(g,new ArrayList<>());for(int i=0;i<all.length();i++){JSONObject x=all.optJSONObject(i);if(x!=null&&match(x,q))groups.get(group(x.optString("kind"))).add(x);}int shown=0;for(Map.Entry<String,List<JSONObject>> e:groups.entrySet()){if(e.getValue().isEmpty()||customersOnly&&!e.getKey().equals("CUSTOMERS"))continue;TextView gh=txt(e.getKey(),11,MUTED);gh.setTypeface(null,Typeface.BOLD);gh.setLetterSpacing(.08f);results.addView(gh,margin(13));for(JSONObject x:e.getValue()){if(shown>=80)break;results.addView(card(x),margin(6));shown++;}}if(shown==0)results.addView(txt(q.isEmpty()?"Start typing to search.":"No matching customers, invoices, orders or items.",15,MUTED),margin(22));}
 private LinearLayout.LayoutParams margin(int top){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(top),0,0);return p;}
 private View card(JSONObject x){LinearLayout c=col();c.setPadding(dp(15),dp(12),dp(15),dp(12));c.setBackground(shape(SURFACE,14));TextView t=txt(x.optString("title","Result"),16,NAVY);t.setTypeface(null,Typeface.BOLD);c.addView(t);String detail=x.optString("subtitle");if(!x.optString("number").isEmpty()&&!detail.contains(x.optString("number")))detail=(detail.isEmpty()?"":detail+" • ")+x.optString("number");c.addView(txt(detail,12,MUTED));if(x.has("amount")&&Math.abs(x.optDouble("amount"))>0)c.addView(txt(money.format(Math.abs(x.optDouble("amount"))),14,TEAL));c.setOnClickListener(v->open(x));c.setFocusable(true);return c;}
 private void open(JSONObject x){String k=x.optString("kind"),party=x.optString("party",x.optString("ledger"));if(customerKind(k)&&!party.isEmpty()){startActivity(new Intent(this,Customer360Activity.class).putExtra(Customer360Activity.EXTRA_PARTY,party));return;}if(k.equals("order")){startActivity(new Intent(this,OrdersActivity.class));return;}StringBuilder s=new StringBuilder();s.append(x.optString("title","Result"));if(!x.optString("subtitle").isEmpty())s.append("\n").append(x.optString("subtitle"));if(!x.optString("date").isEmpty())s.append("\nDate: ").append(x.optString("date"));if(x.has("amount")&&Math.abs(x.optDouble("amount"))>0)s.append("\nAmount: ").append(money.format(Math.abs(x.optDouble("amount"))));AlertDialog.Builder b=new AlertDialog.Builder(this).setTitle(invoiceKind(k)?"Invoice / item result":"Search result").setMessage(s.toString()).setNegativeButton("Close",null).setNeutralButton("Share",(d,w)->ShareCenter.shareText(this,"Share details",s.toString()));if(!party.isEmpty())b.setPositiveButton("Customer 360",(d,w)->startActivity(new Intent(this,Customer360Activity.class).putExtra(Customer360Activity.EXTRA_PARTY,party)));b.show();}
}
